`timescale 1ns/1ps
// One bench for the RTL (GATE 0), the netlist without delays (1) and the netlist with the delays
// of the SDF file (2). It does not count cycles: it starts an operation and compares the result
// when `done` comes. Each vector row is one step: kind, a, b, cfg, idle cycles before, expected.
//   kind 0: reset   1: operation   2: operation that a reset cuts off
// mc_timing is generated by the runner: the clock period, the time at which cfg changes after
// the rising edge, and for GATE 2 the SDF annotation and the check limits of every flop.
module mc_tb;
    parameter GATE = 0, MUTATION = 0;
    reg clk = 0, rst_n = 0, start = 0, cfg = 0, cfg_next = 0;
    reg [5:0] a = 0, b = 0;
    wire busy, done;
    wire [12:0] result;
    mc_timing t();
    // The netlist has no parameters: synthesis already fixed MUTATION.
    generate if (GATE != 0) begin : g_gate
        mc_scale dut(.*);
    end else begin : g_rtl
        mc_scale #(.MUTATION(MUTATION)) dut(.*);
    end endgenerate
    always #(t.PERIOD / 2.0) clk = ~clk;
    // Every other input changes at the falling edge. cfg changes CFG_AT after the rising edge.
    always @(posedge clk) cfg <= #(t.CFG_AT) cfg_next;
    integer fd, n, checks = 0, operations = 0, aborted = 0, waited;
    reg [15:0] v[0:5];
    reg previous_cfg = 0, was_reset = 0;
    string vectors, wave;
    task fail(input string label);
        begin $display("CHECK_FAIL %s", label);
              $fatal(1, "step=%0d busy=%b done=%b result=%h", checks, busy, done, result); end
    endtask
    task cycle;
        begin
            @(negedge clk);
            if (was_reset && (^{busy, done}) === 1'bx) fail("MC_X");
        end
    endtask
    initial begin
        if (!$value$plusargs("VECTORS=%s", vectors) || !$value$plusargs("WAVE=%s", wave)) $fatal(1, "arguments required");
        $dumpfile(wave); $dumpvars(0, mc_tb);
        if (GATE == 2) $display("VIEW sdf"); else if (GATE == 1) $display("VIEW gate"); else $display("VIEW rtl");
        fd = $fopen(vectors, "r"); if (!fd) $fatal(1, "vectors missing");
        repeat (2) @(negedge clk);
        while (!$feof(fd)) begin
            n = $fscanf(fd, "%h %h %h %h %h %h\n", v[0], v[1], v[2], v[3], v[4], v[5]);
            if (n != 6) $fatal(1, "bad row");
            if (v[0] == 0) begin
                rst_n = 0; start = 0; repeat (2) @(negedge clk);
                rst_n = 1; cycle; was_reset = 1;
                if (busy !== 1'b0 || done !== 1'b0) fail("MC_RESET");
            end else begin
                cfg_next = v[3][0];
                cycle;  // cfg arrives during this cycle or, when it is late, during the start cycle
                repeat (v[4]) begin cycle; if (done !== 1'b0) fail("MC_CONTROL"); end
                if (busy !== 1'b0) fail("MC_CONTROL");
                a = v[1][5:0]; b = v[2][5:0]; start = 1;
                cycle; start = 0;
                if (busy !== 1'b1) fail("MC_CONTROL");
                if (v[0] == 2) begin
                    rst_n = 0; repeat (2) @(negedge clk); rst_n = 1;
                    repeat (4) begin cycle; if (busy !== 1'b0 || done !== 1'b0) fail("MC_RESET"); end
                    aborted = aborted + 1; $display("COVER reset/mid-operation");
                end else begin
                    waited = 0;
                    while (done !== 1'b1) begin
                        if (waited == 6) fail("MC_TIMEOUT");
                        cycle; waited = waited + 1;
                    end
                    if (result !== v[5][12:0]) fail("MC_DATA");
                    if (busy !== 1'b0) fail("MC_CONTROL");
                    operations = operations + 1;
                    if (a == 0 || b == 0) $display("COVER operand/zero");
                    if (a == 63 && b == 63) $display("COVER operand/largest");
                    if (a == 1 || b == 1) $display("COVER operand/one");
                    if (cfg) $display("COVER cfg/doubled"); else $display("COVER cfg/plain");
                    if (cfg != previous_cfg && v[4] == 0) $display("COVER cfg/changed-at-start");
                    if (cfg != previous_cfg && v[4] != 0) $display("COVER cfg/changed-while-idle");
                    if (v[4] == 0) $display("COVER flow/back-to-back"); else $display("COVER flow/idle-gap");
                    previous_cfg = cfg;
                end
            end
            checks = checks + 1;
        end
        cycle; if (done !== 1'b0) fail("MC_CONTROL");
        $display("COUNT operations=%0d", operations);
        $display("COUNT aborted=%0d", aborted);
        $display("COUNT timing_violations=%0d", timing_pkg::violations);
        $display("RESULT PASS checks=%0d", checks);
        $finish;
    end
endmodule
